160	      toggle.checked = completed;
161	      toggle.addEventListener('change', function () {
162	        todos = todos.map(function (t) {
163	          return t.id === todo.id ? Object.assign({}, t, { completed: toggle.checked }) : t;
164	        });
165	        save(todos);
166	        render();
167	      });
168	
169	      var text = document.createElement('span');
170	      text.className = 'text';
171	      text.setAttribute('data-testid', 'todo-text');
172	      text.textContent = todo.text;
173	
174	      var del = document.createElement('button');
175	      del.type = 'button';
176	      del.className = 'delete';
177	      del.setAttribute('data-testid', 'todo-delete');
178	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
179	      del.textContent = 'Delete';
180	      del.addEventListener('click', function () {
181	        todos = todos.filter(function (t) { return t.id !== todo.id; });
182	        save(todos);
183	        render();
184	      });
185	
186	      li.appendChild(toggle);
187	      li.appendChild(text);
188	      if (typeof todo.due === 'string' && DUE_PATTERN.test(todo.due)) {
189	        var due = document.createElement('span');
190	        due.className = 'due';
191	        due.setAttribute('data-testid', 'todo-due-date');
192	        due.textContent = (overdue ? 'Overdue · ' : 'Due ') + formatDue(todo.due);
193	        li.appendChild(due);
194	      }
195	      li.appendChild(del);
196	      list.appendChild(li);
197	    });
198	    empty.textContent = todos.length === 0 ? EMPTY_TEXT.none : (EMPTY_TEXT[filter] || '');
199	    empty.hidden = shown.length > 0;
200	  }
201	
202	  form.addEventListener('submit', function (event) {
203	    event.preventDefault();
204	    var value = input.value.trim();
205	    if (!value) return;
206	    var todo = { id: makeId(), text: value, createdAt: Date.now(), completed: false };
207	    if (DUE_PATTERN.test(dueInput.value)) todo.due = dueInput.value;
208	    todos.push(todo);
209	    save(todos);
210	    input.value = '';
211	    dueInput.value = '';
212	    input.focus();
213	    render();
214	  });
215	
216	  // Today may have changed while the tab was hidden (e.g. overnight).
217	  document.addEventListener('visibilitychange', function () {
218	    if (!document.hidden) render();
219	  });
220	
221	  render();
